<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>About {{ config('platform.name') }}</title><style>*{box-sizing:border-box}body{margin:0;background:#f7f9fc;color:#17233c;font:16px/1.7 Inter,system-ui}.hero{padding:54px 5%;background:linear-gradient(135deg,#eef5ff,#fff,#effcf5)}.wrap{width:min(1160px,100%);margin:auto}.tag{display:inline-block;padding:7px 13px;border-radius:999px;background:#eaf1ff;color:#1769ff;font-size:12px;font-weight:800}.hero h1{max-width:900px;margin:14px 0;font-size:clamp(38px,5vw,58px);line-height:1.08}.hero h1 span{color:#1769ff}.hero p{max-width:780px;color:#697890;font-size:17px}.stats{display:flex;gap:35px;flex-wrap:wrap;margin-top:25px}.stats strong{display:block;font-size:24px}.stats small{color:#697890}.section{padding:55px 5%}.center{max-width:850px;margin:0 auto 35px;text-align:center}.center h2{font-size:36px;line-height:1.2}.center p,.card p{color:#697890}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:17px}.card{padding:25px;border:1px solid #e1e7f0;border-radius:17px;background:#fff;transition:.2s}.card:hover{transform:translateY(-5px);border-color:#1769ff;box-shadow:0 16px 35px #1769ff15}.number{display:grid;place-items:center;width:44px;height:44px;border-radius:12px;background:#eef4ff;color:#1769ff;font-weight:800}.card h3{margin:13px 0 5px}.tech{background:#101d33;color:#fff}.tech h2{margin-top:0}.tags{display:flex;flex-wrap:wrap;gap:8px}.tags a{padding:8px 11px;border:1px solid #ffffff20;border-radius:8px;background:#ffffff12;color:#fff;text-decoration:none;font-size:12px}.contact{display:flex;align-items:center;justify-content:space-between;gap:22px;padding:30px;border-radius:18px;background:#fff;border:1px solid #e1e7f0}.contact h2{margin:4px 0}.contact a{color:#1769ff;font-weight:700;text-decoration:none}@media(max-width:760px){.grid{grid-template-columns:1fr}.contact{align-items:flex-start;flex-direction:column}}</style></head><body><section class="hero"><div class="wrap"><span class="tag">The complete career marketplace</span><h1>Don’t search everywhere.<br><span>Build your career in one place.</span></h1><p>{{ config('platform.name') }} brings verified job discovery, learning, practice and interview preparation into one connected platform.</p><div class="stats"><div><strong>{{ number_format($stats['jobs']) }}</strong><small>Active opportunities</small></div><div><strong>{{ number_format($stats['companies']) }}</strong><small>Companies hiring</small></div><div><strong>{{ number_format($technologies->count()) }}</strong><small>Technology paths</small></div></div></div></section><main><section class="section"><div class="wrap"><div class="center"><span class="tag">Who we are</span><h2>More than a job portal. We are a career ecosystem.</h2><p>Opportunities and preparation resources are scattered across many websites. We connect the important parts of a student’s journey while every application remains linked to its official source.</p></div><div class="grid">@foreach([['Discover','Search synchronized openings using meaningful filters.'],['Learn','Build skills through structured engineering paths.'],['Practise','Use focused interview preparation and coding tools.'],['Prepare','Understand roles, requirements and technologies.'],['Apply','Continue safely to the official employer website.'],['Grow','Keep learning as opportunities and markets change.']] as $index=>$item)<article class="card"><div class="number">{{ str_pad($index+1,2,'0',STR_PAD_LEFT) }}</div><h3>{{ $item[0] }}</h3><p>{{ $item[1] }}</p></article>@endforeach</div></div></section><section class="section tech"><div class="wrap"><h2>Explore technologies and build future-ready skills.</h2><div class="tags">@foreach($technologies as $technology)<a href="{{ route('home') }}?q={{ urlencode($technology) }}#jobs">{{ $technology }}</a>@endforeach</div></div></section><section class="section"><div class="wrap contact"><div><span class="tag"